133→// resolveTranscriptRef computes the transcript path from the session ID.
134→// Copilot CLI stores transcripts at ~/.copilot/session-state/<sessionId>/events.jsonl.
135→// The userPromptSubmitted hook does not include a transcriptPath field, so we compute it.
136→func (c *CopilotCLIAgent) resolveTranscriptRef(ctx context.Context, sessionID string) string {
137→	if override := os.Getenv("ENTIRE_TEST_COPILOT_SESSION_DIR"); override != "" {
138→		return filepath.Join(override, sessionID, "events.jsonl")
139→	}
140→
141→	homeDir, err := os.UserHomeDir()
142→	if err != nil {
143→		logging.Warn(ctx, "copilot-cli: failed to get home directory for transcript resolution", "err", err)
144→		return ""
145→	}
146→
147→	return filepath.Join(homeDir, ".copilot", "session-state", sessionID, "events.jsonl")
148→}
