412→// CapturePreTaskState captures current untracked files before a Task execution
413→// and saves them to a state file.
414→// Works correctly from any subdirectory within the repository.
415→func CapturePreTaskState(ctx context.Context, toolUseID string) error {
416→	if toolUseID == "" {
417→		return errors.New("tool_use_id is required")
418→	}
419→
420→	// Get absolute path for tmp directory
421→	tmpDirAbs, err := paths.AbsPath(ctx, paths.EntireTmpDir)
422→	if err != nil {
423→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
424→	}
425→
426→	// Create tmp directory if it doesn't exist
427→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
428→		return fmt.Errorf("failed to create tmp directory: %w", err)
429→	}
430→
431→	// Get list of untracked files (excluding .entire directory itself)
432→	untrackedFiles, err := getUntrackedFilesForState(ctx)
433→	if err != nil {
434→		return fmt.Errorf("failed to get untracked files: %w", err)
435→	}
436→
437→	// Create state file
438→	stateFile := preTaskStateFile(ctx, toolUseID)
439→	state := PreTaskState{
440→		ToolUseID:      toolUseID,
441→		Timestamp:      time.Now().UTC().Format(time.RFC3339),
442→		UntrackedFiles: untrackedFiles,
443→	}
444→
445→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
446→	if err != nil {
447→		return fmt.Errorf("failed to marshal state: %w", err)
448→	}
449→
450→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
451→		return fmt.Errorf("failed to write state file: %w", err)
452→	}
453→
454→	logging.Debug(logging.WithComponent(ctx, "state"), "captured state before task",
455→		slog.Int("untracked_files", len(untrackedFiles)))
456→	return nil
457→}
