 16→// HooksFileName is the hooks file managed by Entire for Copilot CLI.
 17→const HooksFileName = "entire.json"
 18→
 19→// hooksDir is the directory within the repo where Copilot CLI looks for hook configs.
 20→const hooksDir = ".github/hooks"
 21→
 22→// entireHookPrefixes are command prefixes that identify Entire hooks in the bash field.
 23→var entireHookPrefixes = []string{
 24→	"entire ",
 25→	"go run ${COPILOT_PROJECT_DIR}/cmd/entire/main.go ",
 26→}
 27→
 28→// hookConfigKey maps our kebab-case hook names to camelCase JSON keys.
 29→var hookConfigKey = map[string]string{
 30→	HookNameUserPromptSubmitted: "userPromptSubmitted",
 31→	HookNameSessionStart:        "sessionStart",
 32→	HookNameAgentStop:           "agentStop",
 33→	HookNameSessionEnd:          "sessionEnd",
 34→	HookNameSubagentStop:        "subagentStop",
 35→	HookNamePreToolUse:          "preToolUse",
 36→	HookNamePostToolUse:         "postToolUse",
 37→	HookNameErrorOccurred:       "errorOccurred",
 38→}
