241→// GetSupportedHooks returns the hook types Copilot CLI supports.
242→func (c *CopilotCLIAgent) GetSupportedHooks() []agent.HookType {
243→	return []agent.HookType{
244→		agent.HookSessionStart,
245→		agent.HookSessionEnd,
246→		agent.HookUserPromptSubmit,
247→		agent.HookStop,
248→		agent.HookPreToolUse,
249→		agent.HookPostToolUse,
250→	}
251→}
