253→// parseCopilotHookType parses a specific hook type from rawHooks into the target slice.
254→// Silently ignores parse errors (leaves target unchanged).
255→func parseCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CopilotHookEntry) {
256→	if data, ok := rawHooks[hookType]; ok {
257→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
258→		json.Unmarshal(data, target)
259→	}
260→}
261→
262→// marshalCopilotHookType marshals a hook type back into rawHooks.
263→// If the slice is empty, removes the key from rawHooks.
264→func marshalCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CopilotHookEntry) {
265→	if len(entries) == 0 {
266→		delete(rawHooks, hookType)
267→		return
268→	}
269→	data, err := json.Marshal(entries)
270→	if err != nil {
271→		return // Silently ignore marshal errors (shouldn't happen)
272→	}
273→	rawHooks[hookType] = data
274→}
275→
276→// hookBashExists checks if a hook with the given bash command already exists.
277→func hookBashExists(entries []CopilotHookEntry, bash string) bool {
278→	for _, entry := range entries {
279→		if entry.Bash == bash {
280→			return true
281→		}
282→	}
283→	return false
284→}
285→
286→// isEntireHook checks if a hook entry's bash command belongs to Entire.
287→func isEntireHook(bash string) bool {
288→	for _, prefix := range entireHookPrefixes {
289→		if strings.HasPrefix(bash, prefix) {
290→			return true
291→		}
292→	}
293→	return false
294→}
295→
296→// hasEntireHook checks if any entry in the slice is an Entire hook.
297→func hasEntireHook(entries []CopilotHookEntry) bool {
298→	for _, entry := range entries {
299→		if isEntireHook(entry.Bash) {
300→			return true
301→		}
302→	}
303→	return false
304→}
305→
306→// removeEntireHooks removes all Entire hooks from the slice.
307→func removeEntireHooks(entries []CopilotHookEntry) []CopilotHookEntry {
308→	result := make([]CopilotHookEntry, 0, len(entries))
309→	for _, entry := range entries {
310→		if !isEntireHook(entry.Bash) {
311→			result = append(result, entry)
312→		}
313→	}
314→	return result
315→}
