484→func handleLifecycleSubagentEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
485→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
486→	if event.SubagentType == "" && event.TaskDescription == "" {
487→		// Extract subagent type and description from tool input
488→		event.SubagentType, event.TaskDescription = ParseSubagentTypeAndDescription(event.ToolInput)
489→	}
490→
491→	// Determine subagent transcript path
492→	transcriptDir := filepath.Dir(event.SessionRef)
493→	var subagentTranscriptPath string
494→	if event.SubagentID != "" {
495→		subagentTranscriptPath = AgentTranscriptPath(transcriptDir, event.SubagentID)
496→		if !fileExists(subagentTranscriptPath) {
497→			subagentTranscriptPath = ""
498→		}
499→	}
500→
501→	// Log context
502→	subagentEndAttrs := []any{
503→		slog.String("event", event.Type.String()),
504→		slog.String("session_id", event.SessionID),
505→		slog.String("tool_use_id", event.ToolUseID),
506→	}
507→	if event.SubagentID != "" {
508→		subagentEndAttrs = append(subagentEndAttrs, slog.String("agent_id", event.SubagentID))
509→	}
510→	if subagentTranscriptPath != "" {
511→		subagentEndAttrs = append(subagentEndAttrs, slog.String("subagent_transcript", subagentTranscriptPath))
512→	}
513→	logging.Info(logCtx, "subagent completed", subagentEndAttrs...)
514→
515→	// Extract modified files from subagent transcript
516→	var modifiedFiles []string
517→	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok {
518→		transcriptToScan := event.SessionRef
519→		if subagentTranscriptPath != "" {
520→			transcriptToScan = subagentTranscriptPath
521→		}
522→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptToScan, 0); fileErr != nil {
523→			logging.Warn(logCtx, "failed to extract modified files from subagent",
524→				slog.String("error", fileErr.Error()))
525→		} else {
526→			modifiedFiles = files
527→		}
528→	}
529→
530→	// Load pre-task state and detect file changes.
531→	// If no pre-task state exists (agent doesn't support pre-task hook), fall back
532→	// to the session's pre-prompt state. Without either, DetectFileChanges receives
533→	// nil and treats ALL untracked files as new — which would create spurious task
534→	// checkpoints for pre-existing untracked files (e.g., .github/hooks/entire.json).
535→	preState, err := LoadPreTaskState(ctx, event.ToolUseID)
536→	if err != nil {
537→		logging.Warn(logCtx, "failed to load pre-task state",
538→			slog.String("error", err.Error()))
539→	}
540→	var preUntrackedFiles []string
541→	if preState != nil {
542→		preUntrackedFiles = preState.PreUntrackedFiles()
543→	} else if event.SessionID != "" {
544→		// Fall back to session's pre-prompt state for agents without pre-task hooks
545→		prePromptState, ppErr := LoadPrePromptState(ctx, event.SessionID)
546→		if ppErr != nil {
547→			logging.Warn(logCtx, "failed to load pre-prompt state as fallback",
548→				slog.String("error", ppErr.Error()))
549→		}
550→		if prePromptState != nil {
551→			preUntrackedFiles = prePromptState.PreUntrackedFiles()
552→			logging.Debug(logCtx, "using pre-prompt state as fallback for task file detection",
553→				slog.Int("pre_existing_untracked_files", len(preUntrackedFiles)))
554→		}
555→	}
556→	changes, err := DetectFileChanges(ctx, preUntrackedFiles)
557→	if err != nil {
558→		logging.Warn(logCtx, "failed to compute file changes",
559→			slog.String("error", err.Error()))
560→	}
561→
562→	// Get worktree root and normalize paths
563→	repoRoot, err := paths.WorktreeRoot(ctx)
564→	if err != nil {
565→		return fmt.Errorf("failed to get worktree root: %w", err)
566→	}
567→
568→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
569→	var relNewFiles, relDeletedFiles []string
570→	if changes != nil {
571→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
572→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
573→		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
574→	}
575→
576→	// If no changes, skip
577→	if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 && len(relDeletedFiles) == 0 {
578→		logging.Info(logCtx, "no file changes detected, skipping task checkpoint")
