583→	// Find checkpoint UUID from main transcript (best-effort)
584→	var checkpointUUID string
585→	// Use the existing CLI-level checkpoint UUID finder
586→	mainLines, _ := parseTranscriptForCheckpointUUID(event.SessionRef) //nolint:errcheck // best-effort
587→	if mainLines != nil {
