// as new (the nil-untracked path through DetectFileChanges). This is the existing behavior
// before the fallback was added — it creates a task checkpoint because untracked files
// look "new".
func TestHandleLifecycleSubagentEnd_NoPrePromptState_NoPreTaskState(t *testing.T) {
	// Cannot use t.Parallel() because we use t.Chdir()
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

