  1→package agents
  2→
  3→import (
  4→	"fmt"
  5→	"os"
  6→	"os/exec"
  7→	"regexp"
  8→	"strings"
  9→	"time"
 10→)
 11→
 12→// TmuxSession implements Session using tmux for PTY-based interactive agents.
 13→type TmuxSession struct {
 14→	name         string
 15→	stableAtSend string   // stable content snapshot when Send was last called
 16→	cleanups     []func() // run on Close
 17→}
 18→
 19→// OnClose registers a function to run when the session is closed.
 20→func (s *TmuxSession) OnClose(fn func()) {
 21→	s.cleanups = append(s.cleanups, fn)
 22→}
 23→
 24→// NewTmuxSession creates a new tmux session running the given command in dir.
 25→// unsetEnv lists environment variable names to strip from the session.
 26→func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
 27→	s := &TmuxSession{name: name}
 28→
 29→	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
 30→	// Build a shell command string, prefixed with env -u for each var to strip.
 31→	// All arguments are shell-quoted to prevent injection or splitting.
 32→	// PATH is always forwarded from the current process so that the freshly-built
 33→	// "entire" binary (prepended to PATH by main_test.go) is available inside the
 34→	// tmux session. Without this, tmux inherits the server's environment which may
 35→	// have an older binary (or none at all).
 36→	var parts []string
 37→	parts = append(parts, "env", "PATH="+shellQuote(os.Getenv("PATH")))
 38→	for _, v := range unsetEnv {
 39→		parts = append(parts, "-u", shellQuote(v))
 40→	}
 41→	parts = append(parts, shellQuote(command))
 42→	for _, a := range args {
 43→		parts = append(parts, shellQuote(a))
 44→	}
 45→	tmuxArgs = append(tmuxArgs, strings.Join(parts, " "))
 46→
 47→	cmd := exec.Command("tmux", tmuxArgs...)
 48→	if out, err := cmd.CombinedOutput(); err != nil {
 49→		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
 50→	}
 51→	// Keep the pane around after the command exits so we can capture error output.
 52→	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
 53→	_ = setCmd.Run()
 54→	return s, nil
 55→}
 56→
 57→func (s *TmuxSession) Send(input string) error {
 58→	preSend := stableContent(s.Capture())
 59→	// Send text and Enter separately — Claude's TUI can swallow Enter
 60→	// if it arrives before the input handler finishes processing the text.
 61→	if err := s.SendKeys(input); err != nil {
 62→		return err
 63→	}
 64→	time.Sleep(200 * time.Millisecond)
 65→	if err := s.SendKeys("Enter"); err != nil {
 66→		return err
 67→	}
 68→
 69→	// Wait for the terminal to reflect the echoed input, then snapshot.
 70→	// This ensures WaitFor compares against post-echo content, preventing
 71→	// false matches on prompt characters (e.g. ❯) in the echoed input.
 72→	deadline := time.Now().Add(5 * time.Second)
 73→	for time.Now().Before(deadline) {
 74→		time.Sleep(200 * time.Millisecond)
 75→		current := stableContent(s.Capture())
 76→		if current != preSend {
 77→			s.stableAtSend = current
 78→			return nil
 79→		}
 80→	}
 81→	s.stableAtSend = stableContent(s.Capture())
 82→	return nil
 83→}
 84→
 85→// SendKeys sends raw tmux key names without appending Enter.
 86→func (s *TmuxSession) SendKeys(keys ...string) error {
 87→	args := append([]string{"send-keys", "-t", s.name}, keys...)
 88→	cmd := exec.Command("tmux", args...)
 89→	out, err := cmd.CombinedOutput()
 90→	if err != nil {
 91→		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
 92→	}
 93→	return nil
 94→}
 95→
 96→const (
 97→	settleTime   = 2 * time.Second
 98→	pollInterval = 500 * time.Millisecond
 99→)
100→
101→// stableContent returns the content with the last few lines stripped,
102→// so that TUI status bar updates don't prevent the settle timer.
103→func stableContent(content string) string {
104→	lines := strings.Split(content, "\n")
105→	if len(lines) > 3 {
106→		lines = lines[:len(lines)-3]
107→	}
108→	return strings.Join(lines, "\n")
109→}
110→
111→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
112→	re, err := regexp.Compile(pattern)
113→	if err != nil {
114→		return "", fmt.Errorf("invalid pattern: %w", err)
115→	}
116→
117→	deadline := time.Now().Add(timeout)
118→	var matchedAt time.Time
119→	var lastStable string
120→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
121→
122→	for time.Now().Before(deadline) {
123→		content := s.Capture()
124→		stable := stableContent(content)
125→
126→		if !re.MatchString(content) {
127→			// Pattern lost — reset
128→			matchedAt = time.Time{}
129→			lastStable = ""
130→			time.Sleep(pollInterval)
131→			continue
132→		}
133→
134→		// Detect content change since Send was called
135→		if !contentChanged && stable != s.stableAtSend {
136→			contentChanged = true
137→		}
138→
139→		if stable != lastStable {
140→			// Pattern matches but content is still changing — reset settle timer
141→			matchedAt = time.Now()
142→			lastStable = stable
143→			time.Sleep(pollInterval)
144→			continue
145→		}
146→
147→		// Pattern matches and content hasn't changed since matchedAt.
148→		// Only settle if content changed at least once after Send
149→		// (prevents false settle on echoed input before agent starts).
150→		if contentChanged && time.Since(matchedAt) >= settleTime {
151→			return content, nil
152→		}
153→
154→		time.Sleep(pollInterval)
155→	}
156→	content := s.Capture()
157→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
158→}
159→
160→func (s *TmuxSession) Capture() string {
161→	cmd := exec.Command("tmux", "capture-pane", "-t", s.name, "-p")
162→	out, _ := cmd.Output()
163→	return strings.TrimRight(string(out), "\n")
164→}
165→
166→func (s *TmuxSession) Close() error {
167→	for _, fn := range s.cleanups {
168→		fn()
169→	}
170→	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
171→	out, err := cmd.CombinedOutput()
172→	if err != nil {
173→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
174→	}
175→	return nil
176→}
177→
178→// shellQuote wraps s in single quotes with proper escaping for POSIX shells.
179→func shellQuote(s string) string {
180→	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
181→}
