 14→func init() {
 15→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "copilot-cli" {
 16→		return
 17→	}
 18→	Register(&CopilotCLI{})
 19→}
 20→
 21→type CopilotCLI struct{}
 22→
 23→func (c *CopilotCLI) Name() string               { return "copilot-cli" }
 24→func (c *CopilotCLI) Binary() string             { return "copilot" }
 25→func (c *CopilotCLI) EntireAgent() string        { return "copilot-cli" }
 26→func (c *CopilotCLI) PromptPattern() string      { return `❯` }
 27→func (c *CopilotCLI) TimeoutMultiplier() float64 { return 1.5 }
 28→
 29→func (c *CopilotCLI) IsTransientError(out Output, err error) bool {
 30→	if errors.Is(err, context.DeadlineExceeded) {
 31→		return true
 32→	}
 33→	combined := out.Stdout + out.Stderr
 34→	for _, p := range []string{
 35→		"overloaded",
 36→		"rate limit",
 37→		"503",
 38→		"529",
 39→		"ECONNRESET",
 40→		"ETIMEDOUT",
 41→		"Too Many Requests",
 42→	} {
 43→		if strings.Contains(combined, p) {
 44→			return true
 45→		}
 46→	}
 47→	return false
 48→}
 49→
 50→func (c *CopilotCLI) Bootstrap() error {
 51→	// Copilot CLI uses GitHub authentication (gh auth or GITHUB_TOKEN).
 52→	// No additional bootstrap needed — auth should be pre-configured.
 53→	return nil
 54→}
