 56→func (c *CopilotCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 57→	cfg := &runConfig{Model: "claude-haiku-4.5"}
 58→	for _, o := range opts {
 59→		o(cfg)
 60→	}
 61→
 62→	timeout := 60 * time.Second
 63→	if cfg.PromptTimeout > 0 {
 64→		timeout = cfg.PromptTimeout
 65→	}
 66→	promptCtx, cancel := context.WithTimeout(ctx, timeout)
 67→	defer cancel()
 68→
 69→	args := []string{"-p", prompt, "--model", cfg.Model, "--allow-all"}
 70→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--allow-all"}
 71→	cmd := exec.CommandContext(promptCtx, c.Binary(), args...)
 72→	cmd.Dir = dir
 73→	cmd.Stdin = nil
 74→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 75→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
 76→	cmd.Cancel = func() error {
 77→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
 78→	}
 79→	cmd.WaitDelay = 5 * time.Second
 80→
 81→	var stdout, stderr strings.Builder
 82→	cmd.Stdout = &stdout
 83→	cmd.Stderr = &stderr
 84→
 85→	err := cmd.Run()
 86→	exitCode := 0
 87→	if err != nil {
 88→		exitErr := &exec.ExitError{}
 89→		if errors.As(err, &exitErr) {
 90→			exitCode = exitErr.ExitCode()
 91→		} else {
 92→			exitCode = -1
 93→		}
 94→		if promptCtx.Err() == context.DeadlineExceeded {
 95→			err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
 96→		}
 97→	}
 98→
 99→	return Output{
100→		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
101→		Stdout:   stdout.String(),
102→		Stderr:   stderr.String(),
103→		ExitCode: exitCode,
104→	}, err
105→}
106→
107→func (c *CopilotCLI) StartSession(ctx context.Context, dir string) (Session, error) {
108→	name := fmt.Sprintf("copilot-test-%d", time.Now().UnixNano())
109→	s, err := NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", c.Binary(), "--model", "claude-haiku-4.5", "--allow-all")
110→	if err != nil {
111→		return nil, err
112→	}
113→
114→	// Dismiss startup dialogs (folder trust, etc.) then wait for the "❯" prompt.
115→	// Copilot CLI shows a "Confirm folder trust" dialog in interactive mode for
116→	// new directories. "Yes" is pre-selected, so Enter dismisses it.
117→	for range 5 {
118→		content, err := s.WaitFor(`(❯|Enter to select)`, 30*time.Second)
119→		if err != nil {
120→			_ = s.Close()
121→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
122→		}
123→		if strings.Contains(content, "❯") && !strings.Contains(content, "Enter to select") {
124→			break
125→		}
126→		_ = s.SendKeys("Enter")
127→		time.Sleep(500 * time.Millisecond)
128→	}
129→	s.stableAtSend = ""
130→
131→	return s, nil
132→}
